## 5️⃣ Full Minimal Example (HTML + JS)

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>PMTiles + MapLibre</title>
  <link href="https://unpkg.com/maplibre-gl@4.2.0/dist/maplibre-gl.css" rel="stylesheet">
  <style>
    body, html { margin:0; height:100%; }
    #map { width:100%; height:100%; }
  </style>
</head>
<body>
<div id="map"></div>

<script type="module">
  import * as maplibregl from 'https://unpkg.com/maplibre-gl@4.2.0/dist/maplibre-gl.js';
  import * as pmtiles from 'https://cdn.jsdelivr.net/npm/pmtiles@2.7.0/+esm';

  // 1️⃣ Register the protocol
  const protocol = new pmtiles.Protocol();
  maplibregl.addProtocol('pmtiles', protocol.tile);

  // 2️⃣ Define the style (inline for brevity)
  const style = {
    version: 8,
    sources: {
      world: {
        type: 'vector',
        url: 'pmtiles://https://example.com/basemap.pmtiles'
      }
    },
    layers: [
      { id: 'bg', type: 'background', paint: { 'background-color': '#f8f4f0' } },
      {
        id: 'water',
        type: 'fill',
        source: 'world',
        'source-layer': 'water',
        paint: { 'fill-color': '#a0c8f0' }
      },
      {
        id: 'roads',
        type: 'line',
        source: 'world',
        'source-layer': 'road',
        paint: { 'line-color': '#777', 'line-width': 2 }
      }
    ]
  };

  // 3️⃣ Create the map
  const map = new maplibregl.Map({
    container: 'map',
    style,
    center: [0, 0],
    zoom: 2
  });
</script>
</body>
</html>
```

Open the page in a browser, and you should see the vector basemap rendered from the single `basemap.pmtiles` file.

